 lab=ROOT/'labs/numeric_simd/targets';ref=ROOT/'assessor/numeric_simd/targets/numeric_extension.c';build=ROOT/'build/b06-numeric-resources';build.mkdir(parents=True,exist_ok=True);rows=[];artifacts={}
